def update(records, current_user, request):
    if not isinstance(request, dict) or set(request) != {'record_id', 'status'}:
        return {'ok': False, 'error': 'invalid_request'}
    record_id, status = request['record_id'], request['status']
    if not isinstance(record_id, str) or not record_id or not isinstance(status, str) or status not in {'started', 'completed'}:
        return {'ok': False, 'error': 'invalid_request'}
    record = records.get(record_id)
    if record is None or record['owner'] != current_user:
        return {'ok': False, 'error': 'not_found_or_not_allowed'}
    record['status'] = status
    return {'ok': True, 'status': status}

records = {'p-1': {'owner': 'ana', 'status': 'started'}}
assert not update(records, 'ben', {'record_id': 'p-1', 'status': 'completed'})['ok']
assert records['p-1']['status'] == 'started'
assert not update(records, 'ana', {'record_id': 'p-1', 'status': 'completed', 'owner': 'ana'})['ok']
assert update(records, 'ana', {'record_id': 'p-1', 'status': 'completed'})['ok']
print(records['p-1']['status'])
